theorem norm_read_normalised_iterate_sq (hS : 0 < ∑ i, R.weight i) {ℓ : ℕ}
    (hs : Real.sin ((2 * ℓ + 1) * A.angle) ≠ 0) (i : ι) :
    ‖R.read i (normalised (A.good (A.iterate ℓ)))‖ ^ 2 = R.weight i / ∑ j, R.weight j

theorem phaseEq_normalised_good_iterate {ℓ : ℕ}
    (hs : Real.sin ((2 * ℓ + 1) * A.angle) ≠ 0) :
    PhaseEq (normalised (A.good (A.iterate ℓ))) A.goodState

def budgetConst (k : ℕ) : ℕ :=
  let R := 1 + 1920000 * 2 ^ (10 * k)
  let Cc := 40 * R * k + 4
  let CK := 42 + 20 * forrConstant k
  6 * (48002 * 258 * Cc) + 6 * (40 * R * k + 48002 * 69 * CK)

theorem addrLaw_good (hk : 1 ≤ k) {n : ℕ} {ε : ℝ} (ht : 1 ≤ t) (hε : 0 < ε) (hε1 : ε ≤ 1)
    (hn : repetitions k (ε / (40 * t : ℕ)) ≤ n) {x : BitInput (Loc k t C)} {i : Col t} {s : Addr t}
    (hs : ∀ h, P k t (readA x i h) = some (s h)) : 1 - ε ≤ addrLaw n x i s

def disqTree (i : Col t) (s : Addr t) (j : Col t) (hij : j ≠ i) : QueryTree (Loc k t C) :=
  queryWord (2 * t) (fun b => .inr (.inr (.inl ⟨i, (s, ⟨j, hij⟩, b)⟩))) fun w =>
    .query (.inl (j, pointerEquiv (2 * t) w)) (.leaf true) (.leaf false)

theorem Samples.pt_bind {ι β γ : Type} [Fintype β] {n m : ℕ} {g : BitInput ι → β}
    {K : β → BitInput ι → γ → ℝ} (h : Samples n fun x b => pt (g x) b)
    (hK : ∀ b, Samples m (K b)) : Samples (n + m) fun x c => K (g x) x c

theorem cmpProb_winner (hk : 1 ≤ k) {n : ℕ} {x : BitInput (Loc k t C)} {i j : Col t}
    {s : Addr t} (hw : WinsAt (P k t) C (2 * t) (40 * t) x i s) (hne : j ≠ i) :
    addrLaw n x i s ≤ cmpProb n x i j

theorem bind {c₁ c₂ : ℕ} {L₁ : BitInput ι → α → ℝ} {K : α → BitInput ι → β → ℝ}
    (h₁ : Runs c₁ L₁) (h₂ : ∀ a, Runs c₂ (K a)) :
    Runs (c₁ + c₂) fun x b => ∑ a, L₁ x a * K a x b

theorem decodeProb_correct {k t n : ℕ} (hk : 1 ≤ k) {η : ℝ} (h0 : 0 < η)
    (hn : repetitions k η ≤ n) (z : BitInput (ForrelationCoord k t)) {b : Bool}
    (hz : P k t z = some b) : 1 - η ≤ bern (decodeProb k t n z) b

def Samples {ι β : Type} (n : ℕ) (L : BitInput ι → β → ℝ) : Prop :=
  ∃ (Z : Type) (_ : Fintype Z) (o : Z) (out : Z → β) (F : BitInput ι → Reg Z ≃ₗᵢ[ℂ] Reg Z),
    IsCirc n F ∧ ∀ x b, L x b = lawOf (F x (rket o)) out b

theorem Samples.bind {ι β γ : Type} [Fintype β] {n₁ n₂ : ℕ} {L : BitInput ι → β → ℝ}
    {K : β → BitInput ι → γ → ℝ} (h₁ : Samples n₁ L) (h₂ : ∀ b, Samples n₂ (K b)) :
    Samples (n₁ + n₂) fun x c => ∑ b, L x b * K b x c

theorem stage_samples {cc : ℕ} {a : BitInput ι → Col → Col → ℝ}
    (hcmp : ∀ i p, Samples cc fun x b => bern (a x i p) b) (L : List Col) :
    Samples (L.length * cc) fun x o => stageLaw (a x) L o

theorem vall_runs {cV : ℕ} {v : BitInput ι → Col → ℝ}
    (hv : ∀ c, Runs cV fun x b => bern (v x c) b) (L : List Col) :
    Runs (L.length * cV) fun x b => bern (vall (v x) L) b

theorem testLaw_pass {x : BitInput (Loc k t C)} {i : Col t} {s : Addr t}
    (h : ∀ e, localTest C (2 * t) (40 * t) x i s e = true) :
    ∑ b, testLaw x i s (some b) = 0

theorem testLaw_fail {x : BitInput (Loc k t C)} {i : Col t} {s : Addr t} {e₀ : Tests t C}
    (h : localTest C (2 * t) (40 * t) x i s e₀ = false) :
    (Fintype.card (Tests t C) : ℝ)⁻¹ ≤ ∑ b, testLaw x i s (some b)

theorem Runs.ofAmp {ι β : Type} [Fintype ι] [Inhabited ι] [Fintype β] {c : ℕ}
    {f : BitInput ι → ℝ} {q : BitInput ι → β → ℝ}
    (h : Runs c fun x => ampLaw (f x) (q x))
    (hsum : ∀ x, f x + (1 - f x) * ∑ p, q x p / ∑ b, q x b = 1) :
    Runs c fun x b => bern (f x) b

theorem Fkm_QLe (hk : 1 ≤ k) (ht : 1 ≤ t) (hC : CircuitRealises C (P k t)) {n : ℕ}
    (hn : repetitions k (epsval (mValue t) / (40 * t : ℕ)) ≤ n) :
    QLe (totalise (Fkm k t C)) (budget k t n (Fintype.card (Tests t C)))

theorem quantum_inverse_reads {ι Z : Type} [Fintype Z] {n : ℕ}
    {F : BitInput ι → Reg Z ≃ₗᵢ[ℂ] Reg Z} (hF : IsCirc n F) :
    IsCirc n (fun x => (F x).symm)

